arguments.cmd:
cat > /app/output/index.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f7f8fc;
      --surface: #ffffff;
      --ink: #101828;
      --muted: #5d6679;
      --hero-bg: #12182f;
      --hero-ink: #f8f9ff;
      --accent-coral: #ff6b4a;
      --accent-yellow: #ffd84d;
      --accent-green: #5be48d;
      --accent-blue: #5f7cff;
      --stroke: #e8eaf2;
      --radius: 18px;
      --shadow: 0 10px 30px rgba(16, 24, 40, 0.08);
      --container: min(1160px, calc(100% - 2rem));
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: var(--bg);
      color: var(--ink);
      line-height: 1.5;
    }

    h1, h2, h3, h4 { font-family: "Plus Jakarta Sans", Inter, sans-serif; margin: 0; line-height: 1.15; }
    p { margin: 0; color: var(--muted); }
    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }

    .container { width: var(--container); margin-inline: auto; }
    .section { padding: 76px 0; }

    .topbar {
      position: sticky; top: 0; z-index: 30;
      backdrop-filter: blur(10px);
      background: rgba(255,255,255,0.85);
      border-bottom: 1px solid rgba(16,24,40,0.06);
    }
    .topbar-inner {
      width: var(--container);
      margin-inline: auto;
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
    }
    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-family: "Plus Jakarta Sans", sans-serif;
      font-weight: 800;
      font-size: 1.05rem;
      letter-spacing: 0.2px;
    }
    .logo-dot {
      width: 28px; height: 28px; border-radius: 9px;
      background: linear-gradient(135deg, var(--accent-coral), var(--accent-yellow));
      box-shadow: 0 6px 14px rgba(255, 107, 74, 0.35);
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 24px;
      color: #2a3247;
      font-weight: 600;
      font-size: .95rem;
    }
    .nav-actions { display: flex; gap: 12px; align-items: center; }

    .btn {
      border: 0;
      outline: none;
      border-radius: 14px;
      padding: 12px 16px;
      font-weight: 700;
      font-size: .95rem;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 9px;
    }
    .btn:focus-visible { outline: 3px solid #8ab4ff; outline-offset: 2px; }
    .btn:hover { transform: translateY(-1px); }
    .btn-outline {
      background: #fff;
      border: 1px solid var(--stroke);
      color: #24324b;
    }
    .btn-primary {
      color: #101828;
      background: linear-gradient(135deg, var(--accent-yellow), #ffbf29);
      box-shadow: 0 10px 20px rgba(255, 191, 41, 0.36);
    }
    .btn-coral {
      color: #fff;
      background: linear-gradient(135deg, #ff6b4a, #ff5a35);
      box-shadow: 0 14px 24px rgba(255, 90, 53, 0.34);
    }

    .hero-wrap {
      padding: 28px 0 40px;
      background: linear-gradient(180deg, #f5f7fe 0%, #f7f8fc 100%);
    }

    .hero {
      background: radial-gradient(circle at 92% 16%, rgba(95,124,255,.2), transparent 34%),
                  radial-gradient(circle at 75% 77%, rgba(91,228,141,.16), transparent 36%),
                  var(--hero-bg);
      color: var(--hero-ink);
      border-radius: 28px;
      padding: 40px;
      display: grid;
      grid-template-columns: 1.2fr .9fr;
      gap: 28px;
      position: relative;
      overflow: hidden;
      box-shadow: 0 26px 40px rgba(13, 21, 46, .28);
    }
    .hero h1 {
      font-size: clamp(2rem, 5vw, 3.35rem);
      letter-spacing: -.03em;
      margin-bottom: 14px;
    }
    .hero p { color: #d3d8ea; font-size: 1.02rem; max-width: 58ch; }

    .hero-cta {
      margin-top: 26px;
      display: grid;
      gap: 12px;
      max-width: 370px;
    }
    .hero-cta .btn { width: 100%; min-height: 52px; font-size: 1rem; }
    .google-icon {
      width: 18px; height: 18px; border-radius: 50%; background:
      conic-gradient(from 0deg, #ea4335 0 25%, #fbbc05 25% 50%, #34a853 50% 75%, #4285f4 75% 100%);
    }

    .hero-note { font-size: .87rem; color: #b9c2de; margin-top: 8px; }

    .pill-row {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 24px;
    }
    .pill {
      border: 1px solid rgba(255,255,255,.18);
      color: #dce3fa;
      border-radius: 999px;
      padding: 8px 14px;
      font-size: .84rem;
      font-weight: 600;
      background: rgba(255,255,255,.06);
      transition: all .2s ease;
    }
    .pill:hover {
      background: rgba(255, 216, 77, .18);
      color: #fff3be;
      border-color: rgba(255,216,77,.35);
    }

    .hero-card {
      align-self: end;
      background: rgba(255,255,255,.95);
      color: #121a2c;
      border-radius: 22px;
      padding: 18px;
      box-shadow: 0 16px 40px rgba(8, 12, 24, .2);
    }
    .hero-card h3 { font-size: 1.05rem; margin-bottom: 12px; }
    .hero-stamp-grid { display: grid; gap: 10px; }
    .stamp {
      border: 1px solid #edf0f8;
      border-radius: 14px;
      padding: 12px;
      display: grid;
      gap: 3px;
    }
    .stamp strong { font-size: 1rem; }
    .stamp span { font-size: .84rem; color: #5b6378; }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 24px;
    }
    .section-head h2 { font-size: clamp(1.5rem, 3vw, 2.15rem); letter-spacing: -.02em; }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }
    .feature-card {
      background: var(--surface);
      border: 1px solid var(--stroke);
      border-radius: var(--radius);
      padding: 20px;
      box-shadow: var(--shadow);
      transition: transform .25s ease, box-shadow .25s ease;
    }
    .feature-card:hover { transform: translateY(-4px); box-shadow: 0 14px 34px rgba(16,24,40,.12); }
    .feature-badge {
      width: 38px; height: 38px; border-radius: 12px;
      display: inline-grid; place-items: center; font-size: 1.2rem; font-weight: 800;
      margin-bottom: 10px;
      background: linear-gradient(135deg, #ffe4de, #fff4df);
      color: #ff6b4a;
    }

    .stats-band {
      background: linear-gradient(100deg, #1a2350, #25347d);
      color: #fff;
      border-radius: 24px;
      padding: 34px 26px;
      box-shadow: 0 18px 40px rgba(26,35,80,.35);
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }
    .stat {
      background: rgba(255,255,255,.08);
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 16px;
      padding: 18px;
    }
    .stat strong { display: block; font-size: clamp(1.8rem, 4vw, 2.5rem); line-height: 1; margin-bottom: 7px; }
    .stat span { color: #d8e0ff; font-weight: 500; }

    .tabs {
      display: flex;
      gap: 10px;
      overflow: auto;
      padding-bottom: 8px;
      scrollbar-width: thin;
    }
    .tab {
      border: 1px solid var(--stroke);
      border-radius: 999px;
      background: #fff;
      color: #24324b;
      padding: 10px 15px;
      font-weight: 700;
      cursor: pointer;
      white-space: nowrap;
      transition: all .2s ease;
      min-height: 44px;
    }
    .tab.active {
      background: #12182f;
      color: #fff;
      border-color: #12182f;
      box-shadow: 0 8px 20px rgba(18,24,47,.2);
    }

    .course-grid {
      margin-top: 20px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }
    .course-card {
      background: #fff;
      border: 1px solid var(--stroke);
      border-radius: 18px;
      overflow: hidden;
      box-shadow: var(--shadow);
      transition: transform .2s ease, box-shadow .2s ease;
    }
    .course-card:hover { transform: translateY(-4px); box-shadow: 0 16px 34px rgba(16,24,40,.13); }
    .thumb {
      aspect-ratio: 16/10;
      display: grid;
      place-items: center;
      color: #fff;
      font-family: "Plus Jakarta Sans", sans-serif;
      font-weight: 800;
      letter-spacing: .2px;
      font-size: .95rem;
    }
    .thumb.t1 { background: linear-gradient(135deg,#ff8a63,#ffcf57); }
    .thumb.t2 { background: linear-gradient(135deg,#6e9dff,#55d4bb); }
    .thumb.t3 { background: linear-gradient(135deg,#f78fd4,#9f7dff); }
    .thumb.t4 { background: linear-gradient(135deg,#44d98d,#76ecf7); }
    .thumb.t5 { background: linear-gradient(135deg,#ffa07d,#ff6a88); }
    .thumb.t6 { background: linear-gradient(135deg,#7288ff,#c87dff); }

    .course-body { padding: 14px 14px 16px; }
    .course-body h3 { font-size: 1rem; margin-bottom: 8px; }
    .meta-line {
      font-size: .86rem;
      color: #5d6679;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
    }

    .feed-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
    }
    .feed-item {
      background: #fff;
      border: 1px solid var(--stroke);
      border-radius: 16px;
      padding: 14px;
      min-height: 120px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      box-shadow: var(--shadow);
    }

    .teacher-wrap { position: relative; }
    .teacher-scroller {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(230px, 1fr);
      gap: 14px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: 6px;
      scrollbar-width: thin;
    }
    .teacher-card {
      scroll-snap-align: start;
      border-radius: 18px;
      border: 1px solid var(--stroke);
      background: #fff;
      padding: 14px;
      box-shadow: var(--shadow);
      min-height: 230px;
      display: grid;
      align-content: start;
      gap: 11px;
    }
    .avatar {
      width: 72px; height: 72px;
      border-radius: 18px;
      display: grid;
      place-items: center;
      font-family: "Plus Jakarta Sans";
      font-weight: 800;
      color: #fff;
    }
    .a1 { background: linear-gradient(135deg,#ff845f,#ffcc70); }
    .a2 { background: linear-gradient(135deg,#5f7cff,#66d2ff); }
    .a3 { background: linear-gradient(135deg,#6ad98d,#91ec5c); }
    .a4 { background: linear-gradient(135deg,#c07bff,#f080c1); }
    .a5 { background: linear-gradient(135deg,#ff8d8d,#ffb95c); }
    .a6 { background: linear-gradient(135deg,#61d6e9,#5ea3ff); }

    .carousel-nav {
      position: absolute;
      right: 0;
      top: -54px;
      display: flex;
      gap: 8px;
    }
    .circle-btn {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      border: 1px solid var(--stroke);
      background: #fff;
      cursor: pointer;
      font-size: 1.1rem;
      font-weight: 800;
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 16px;
    }
    .quote {
      background: #fff;
      border: 1px solid var(--stroke);
      border-radius: 18px;
      padding: 18px;
      box-shadow: var(--shadow);
    }

    .teams-band {
      background: linear-gradient(135deg, #fff7e6, #fff);
      border: 1px solid #ffefc9;
      border-radius: 20px;
      padding: 24px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 16px;
      align-items: center;
    }

    .faq-list {
      display: grid;
      gap: 10px;
    }
    .faq-item {
      border: 1px solid var(--stroke);
      border-radius: 16px;
      background: #fff;
      overflow: hidden;
    }
    .faq-question {
      width: 100%;
      padding: 16px;
      border: 0;
      background: #fff;
      display: flex;
      align-items: center;
      justify-content: space-between;
      text-align: left;
      font-weight: 700;
      color: #17233b;
      cursor: pointer;
      font-size: .97rem;
      min-height: 56px;
    }
    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height .25s ease;
      border-top: 1px solid transparent;
    }
    .faq-answer-inner { padding: 0 16px 16px; color: #4e576d; }
    .faq-item.active .faq-answer { max-height: 170px; border-top-color: var(--stroke); }

    footer {
      padding: 44px 0 30px;
      background: #11182f;
      color: #d4dbf2;
      margin-top: 56px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 1.3fr repeat(3, 1fr);
      gap: 16px;
    }
    .footer-col h4 { font-size: .95rem; margin-bottom: 10px; color: #fff; }
    .footer-col a { display: block; font-size: .9rem; margin: 6px 0; color: #d4dbf2; }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      margin: -1px;
      padding: 0;
      border: 0;
      overflow: hidden;
      clip: rect(0 0 0 0);
    }

    @media (max-width: 1060px) {
      .hero { grid-template-columns: 1fr; }
      .features-grid, .course-grid { grid-template-columns: repeat(2, 1fr); }
      .feed-grid { grid-template-columns: repeat(2, 1fr); }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 720px) {
      .topbar-inner { height: 72px; }
      .nav-links { display: none; }
      .hero { padding: 24px; border-radius: 22px; }
      .section { padding: 58px 0; }
      .features-grid, .course-grid, .testimonial-grid, .feed-grid, .footer-grid { grid-template-columns: 1fr; }
      .teams-band { grid-template-columns: 1fr; }
      .carousel-nav { position: static; margin-bottom: 10px; }
      .teacher-wrap { display: grid; gap: 10px; }
      .hero-cta { max-width: none; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="topbar-inner">
      <a href="index.html" class="brand" aria-label="CreativeHub home">
        <span class="logo-dot" aria-hidden="true"></span>
        <span>CreativeHub</span>
      </a>
      <nav class="nav-links" aria-label="Primary navigation">
        <a href="index.html">Browse</a>
        <a href="index.html">Pricing</a>
        <a href="index.html">For Teams</a>
      </nav>
      <div class="nav-actions">
        <a href="index.html" class="btn btn-outline" aria-label="Sign in">Sign In</a>
        <a href="index.html" class="btn btn-primary" aria-label="Sign up">Sign Up</a>
      </div>
    </div>
  </header>

  <main>
    <section class="hero-wrap">
      <div class="container">
        <div class="hero" id="hero">
          <div>
            <h1>Learn creative skills from world-class teachers.</h1>
            <p>Join a vibrant creative studio online. Stream thousands of classes in illustration, design, animation, film, and more — with projects that help you build portfolio-ready work.</p>

            <div class="hero-cta" aria-label="Sign up options">
              <button class="btn btn-primary" id="googleSignup" aria-label="Continue with Google">
                <span class="google-icon" aria-hidden="true"></span>
                Continue with Google
              </button>
              <button class="btn btn-coral" id="emailSignup" aria-label="Continue with email">Continue with email</button>
              <p class="hero-note">Start your 7-day free trial today. Cancel anytime.</p>
            </div>

            <div class="pill-row" aria-label="Course categories">
              <a class="pill" href="#courses">Graphic Design</a>
              <a class="pill" href="#courses">Illustration</a>
              <a class="pill" href="#courses">Animation</a>
              <a class="pill" href="#courses">Film &amp; Video</a>
              <a class="pill" href="#courses">Freelance</a>
              <a class="pill" href="#courses">UI/UX Design</a>
            </div>
          </div>

          <aside class="hero-card" aria-label="Why creators choose CreativeHub">
            <h3>Creative momentum starts here</h3>
            <div class="hero-stamp-grid">
              <div class="stamp">
                <strong>425k+ active members</strong>
                <span>Learn together with a thriving global community.</span>
              </div>
              <div class="stamp">
                <strong>30k+ classes</strong>
                <span>From beginner foundations to advanced workflows.</span>
              </div>
              <div class="stamp">
                <strong>Project-based lessons</strong>
                <span>Build real outcomes, not passive watch time.</span>
              </div>
            </div>
          </aside>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="section-head">
          <h2>Why creators choose CreativeHub</h2>
        </div>
        <div class="features-grid">
          <article class="feature-card">
            <div class="feature-badge">✦</div>
            <h3>Learn by doing</h3>
            <p>Hands-on classes with practical projects that sharpen your skills and grow your portfolio.</p>
          </article>
          <article class="feature-card">
            <div class="feature-badge">◉</div>
            <h3>Expert-led paths</h3>
            <p>Guided lessons from industry pros across illustration, design, motion, and creative business.</p>
          </article>
          <article class="feature-card">
            <div class="feature-badge">↗</div>
            <h3>Career-ready outcomes</h3>
            <p>Build confidence, publish your work, and unlock opportunities as a freelancer or in-house creative.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="section" aria-label="Platform statistics">
      <div class="container">
        <div class="stats-band" id="stats">
          <div class="stats-grid">
            <article class="stat"><strong>425k+</strong><span>Members worldwide</span></article>
            <article class="stat"><strong>30k+</strong><span>On-demand classes</span></article>
            <article class="stat"><strong>9k+</strong><span>Expert teachers</span></article>
            <article class="stat"><strong>4.8</strong><span>App store rating</span></article>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="courses">
      <div class="container">
        <div class="section-head">
          <h2>Explore trending classes</h2>
        </div>
        <div class="tabs" role="tablist" aria-label="Course categories" id="categoryTabs"></div>
        <div class="course-grid" id="courseGrid" aria-live="polite"></div>
      </div>
    </section>

    <section class="section" id="creative-feed">
      <div class="container">
        <div class="section-head">
          <h2>From the Creative Feed</h2>
          <a href="index.html" class="btn btn-outline">See all updates</a>
        </div>
        <div class="feed-grid">
          <article class="feed-item"><strong>Daily Prompt</strong><p>Sketch a city scene using only 3 colors and 2 brush types.</p></article>
          <article class="feed-item"><strong>Workshop Replay</strong><p>Master expressive watercolor textures in 30 minutes.</p></article>
          <article class="feed-item"><strong>Community Spotlight</strong><p>How Maria landed her first motion design client.</p></article>
          <article class="feed-item"><strong>Creator Challenge</strong><p>Design a personal brand kit in Figma this weekend.</p></article>
        </div>
      </div>
    </section>

    <section class="section" id="teachers">
      <div class="container">
        <div class="section-head">
          <h2>Learn from Creative Experts</h2>
        </div>
        <div class="teacher-wrap">
          <div class="carousel-nav" aria-label="Teacher carousel navigation">
            <button class="circle-btn" id="teacherPrev" aria-label="Scroll teachers left">←</button>
            <button class="circle-btn" id="teacherNext" aria-label="Scroll teachers right">→</button>
          </div>
          <div class="teacher-scroller" id="teacherScroller" tabindex="0" aria-label="Expert teachers carousel"></div>
        </div>
      </div>
    </section>

    <section class="section" id="testimonials">
      <div class="container">
        <div class="section-head">
          <h2>Loved by creative learners</h2>
        </div>
        <div class="testimonial-grid" id="testimonialGrid"></div>
      </div>
    </section>

    <section class="section" id="teams">
      <div class="container">
        <div class="teams-band">
          <div>
            <h2>Upskill your team, faster</h2>
            <p>Give your team unlimited access to practical creative classes, curated learning paths, and analytics to track growth.</p>
          </div>
          <a href="index.html" class="btn btn-coral">Book a Team Demo</a>
        </div>
      </div>
    </section>

    <section class="section" id="faq">
      <div class="container">
        <div class="section-head">
          <h2>Frequently asked questions</h2>
        </div>
        <div class="faq-list" id="faqList"></div>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container footer-grid">
      <div>
        <a href="index.html" class="brand" style="color:#fff"><span class="logo-dot"></span><span>CreativeHub</span></a>
        <p style="margin-top:12px; color:#c1c9e7; max-width:38ch;">CreativeHub helps artists and creatives grow with hands-on classes, expert feedback, and a global community.</p>
      </div>
      <div class="footer-col">
        <h4>Platform</h4>
        <a href="index.html">Browse classes</a>
        <a href="index.html">Teachers</a>
        <a href="index.html">Pricing</a>
      </div>
      <div class="footer-col">
