          category: ["Featured", "Film & Video", "Animation"],
          thumb: "t6"
        },
        {
          title: "Beat Making Essentials in Ableton Live",
          instructor: "Sofia Kane",
          students: "21,006",
          duration: "3h 44m",
          category: ["Music"],
          thumb: "t2"
        },
        {
          title: "Animating Character Walk Cycles",
          instructor: "Diego Cruz",
          students: "18,451",
          duration: "2h 58m",
          category: ["Animation"],
          thumb: "t6"
        }
      ],
      teachers: [
        { name: "Ari Bennett", role: "Illustrator", cls: "a1" },
        { name: "Noelle Park", role: "Digital Designer", cls: "a2" },
        { name: "Marcus Lee", role: "Animator, Product Designer", cls: "a3" },
        { name: "Iris Morgan", role: "Graphic Designer", cls: "a4" },
        { name: "Lila Chen", role: "Watercolor Artist", cls: "a5" },
        { name: "Dev Walker", role: "Motion Graphics Artist", cls: "a6" }
      ],
      faq: [
        {
          q: "What is CreativeHub?",
          a: "CreativeHub is an online learning platform where creative professionals, hobbyists, and aspiring artists build practical skills through project-based classes."
        },
        {
          q: "What is included in my membership?",
          a: "Membership includes unlimited class access, downloadable resources, project assignments, and access to our global creator community."
        },
        {
          q: "What can I learn?",
          a: "You can explore illustration, animation, video editing, UI/UX design, graphic design, music production, freelancing, and more."
        },
        {
          q: "What happens after my trial is over?",
          a: "After your free trial, your selected plan starts automatically. You can cancel anytime before renewal to avoid charges."
        },
        {
          q: "Can I teach on the platform?",
          a: "Yes. Experienced creators can apply to become teachers and publish project-based classes for our member community."
        }
      ],
      testimonials: [
        { quote: "CreativeHub is the best learning decision I've ever made.", name: "Riley, Illustrator" },
        { quote: "Real-world skills without the financial burden — exactly what I needed.", name: "Jordan, Student Creator" },
        { quote: "It's the one subscription I can't imagine not having.", name: "Avery, Freelance Designer" },
        { quote: "The class structure helps me level up my skills every week.", name: "Sam, Motion Designer" }
      ]
    };

    let activeCategory = "Featured";

    const tabsRoot = document.getElementById("categoryTabs");
    const courseGrid = document.getElementById("courseGrid");
    const teacherScroller = document.getElementById("teacherScroller");
    const faqRoot = document.getElementById("faqList");
    const testimonialGrid = document.getElementById("testimonialGrid");

    function renderTabs() {
      tabsRoot.innerHTML = "";
      DATA.categories.forEach((category) => {
        const btn = document.createElement("button");
        btn.className = `tab ${category === activeCategory ? "active" : ""}`;
        btn.role = "tab";
        btn.setAttribute("aria-selected", String(category === activeCategory));
        btn.textContent = category;
        btn.addEventListener("click", () => {
          activeCategory = category;
          renderTabs();
          renderCourses();
        });
        tabsRoot.appendChild(btn);
      });
    }

    function renderCourses() {
      const filtered = DATA.courses.filter((course) => course.category.includes(activeCategory));
      const content = filtered.length ? filtered : DATA.courses.slice(0, 3);

      courseGrid.innerHTML = content.map((course, index) => `
        <article class="course-card">
          <div class="thumb ${course.thumb}">CreativeHub Class</div>
          <div class="course-body">
            <h3>${course.title}</h3>
            <div class="meta-line"><span>${course.instructor}</span><span>${course.duration}</span></div>
            <div class="meta-line" style="margin-top:6px;"><span>${course.students} students</span><span>${activeCategory}</span></div>
          </div>
        </article>
      `).join("");
    }

    function renderTeachers() {
      teacherScroller.innerHTML = DATA.teachers.map((t) => {
        const initials = t.name.split(" ").map(n => n[0]).join("").slice(0,2).toUpperCase();
        return `
          <article class="teacher-card" aria-label="${t.name}, ${t.role}">
            <div class="avatar ${t.cls}" aria-hidden="true">${initials}</div>
            <h3>${t.name}</h3>
            <p>${t.role}</p>
            <a href="index.html" class="btn btn-outline" style="margin-top:8px;">View profile</a>
          </article>
        `;
      }).join("");
    }

    function renderTestimonials() {
      testimonialGrid.innerHTML = DATA.testimonials.map((item) => `
        <article class="quote">
          <p style="font-size:1.02rem; color:#17233b;">“${item.quote}”</p>
          <p style="margin-top:10px; font-weight:600; color:#5d6679;">${item.name}</p>
        </article>
      `).join("");
    }

    function renderFaq() {
      faqRoot.innerHTML = DATA.faq.map((item, idx) => `
        <article class="faq-item ${idx === 0 ? "active" : ""}">
          <button class="faq-question" aria-expanded="${idx === 0 ? "true" : "false"}">
            <span>${item.q}</span>
            <span aria-hidden="true">+</span>
          </button>
          <div class="faq-answer" role="region">
            <div class="faq-answer-inner">${item.a}</div>
          </div>
        </article>
      `).join("");

      const items = faqRoot.querySelectorAll(".faq-item");
      items.forEach((item) => {
        const btn = item.querySelector(".faq-question");
        btn.addEventListener("click", () => {
          const isOpen = item.classList.contains("active");
          items.forEach((other) => {
            other.classList.remove("active");
            other.querySelector(".faq-question").setAttribute("aria-expanded", "false");
          });
          if (!isOpen) {
            item.classList.add("active");
            btn.setAttribute("aria-expanded", "true");
          }
        });
      });
    }

    document.getElementById("teacherPrev").addEventListener("click", () => {
      teacherScroller.scrollBy({ left: -260, behavior: "smooth" });
    });
    document.getElementById("teacherNext").addEventListener("click", () => {
      teacherScroller.scrollBy({ left: 260, behavior: "smooth" });
    });

    document.getElementById("googleSignup").addEventListener("click", () => {
      alert("Google sign-up flow would start here.");
    });

    document.getElementById("emailSignup").addEventListener("click", () => {
      alert("Email sign-up form would open here.");
    });

    renderTabs();
    renderCourses();
    renderTeachers();
    renderFaq();
    renderTestimonials();
  </script>
